package com.hms.notifications;
import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/notifications") public class NotificationRetryController {private final TenantRepository tenants;private final NotificationMessageRepository messages;public NotificationRetryController(TenantRepository t,NotificationMessageRepository m){tenants=t;messages=m;} @PostMapping("/{messageId}/retry") public NotificationMessage retry(@PathVariable String tenantSlug,@PathVariable UUID messageId){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));NotificationMessage m=messages.findById(messageId).filter(x->x.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Notification not found"));if(m.getStatus()!=NotificationStatus.FAILED)throw new IllegalArgumentException("Only failed notifications can be retried");messages.updateStatus(messageId,tenant,NotificationStatus.QUEUED,null);return messages.findById(m.getId()).orElseThrow();}}
